def specialFilter(nums):
    def is_odd(n):
        return n % 2 == 1

    def first_digit(n):
        abs_n = abs(n)
        while abs_n >= 10:
            abs_n //= 10
        return abs_n

    def last_digit(n):
        return abs(n) % 10

    count = 0
    for num in nums:
        if num > 10 and is_odd(first_digit(num)) and is_odd(last_digit(num)):
            count += 1
    return count

